pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // The difference: AdjustDifficulty emits but doesn't change difficulty in bug.
        // So we first call AdjustBetAmounts (which is public), then check difficulty.
        // In the reference, AdjustBetAmounts sets betLimit but does not touch difficulty.
        // However, the bug is in AdjustDifficulty, not AdjustBetAmounts.
        // To observe the divergence, we must call AdjustDifficulty first to see the effect.
        // The difference says: after a call to AdjustBetAmounts, difficulty differs.
        // That implies AdjustBetAmounts somehow triggers AdjustDifficulty? No.
        // Actually the description: "after a call to AdjustBetAmounts completes, the value of state variable difficulty differs".
        // That's odd because AdjustBetAmounts does not change difficulty. Let's reason:
        // In the reference, AdjustDifficulty changes difficulty. In bug, it doesn't.
        // If we call AdjustDifficulty(42), then difficulty is 42 in reference, 0 in bug.
        // Then calling AdjustBetAmounts(100) does not change difficulty. So after that call, difficulty still differs.
        // So concrete scenario: call AdjustDifficulty(42), then AdjustBetAmounts(100), then check difficulty.
        // Reference: difficulty = 42; Bug: difficulty = 0.
        vm.prank(address(this));
        c.AdjustDifficulty(42);
        vm.prank(address(this));
        c.AdjustBetAmounts(100);
        // Assert that difficulty is 42 (reference holds, bug breaks)
        assertTrue(c.currentDifficulty() == 42);
    }
}

