contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // 1. Open to public and set difficulty (to avoid division by zero)
        c.OpenToThePublic();
        c.AdjustDifficulty(2);

        // 2. Owner calls AdjustBetAmounts(0): reference -> betLimit=0; bug -> underflow to type(uint256).max
        vm.prank(address(this));
        c.AdjustBetAmounts(0);

        // 3. A real player (EOA) tries to wager with value 1
        address player = address(0x1234);
        vm.deal(player, 1 ether);
        vm.prank(player);
        // Try call; catch revert vs success
        bool wagerSucceeded = true;
        try c.wager{value: 1}() {} catch {
            wagerSucceeded = false;
        }

        // Reference: betLimit=0, so wager with 1 should revert -> wagerSucceeded false
        // Bug: betLimit = type(uint256).max, so check msg.value == betLimit passes (1 == max? no) wait incorrectly?
        // Actually bug: betLimit = 0 - 1 = underflow -> max; wager requires msg.value == betLimit (max), but 1 != max -> also reverts.
        // That's wrong. Let's use wager with value 0: reference passes (0 == 0), bug fails (max != 0).
        // Let's redo:
    }
}

// --- CORRECTED VERSION BELOW (since the above was a draft) ---
// Actually the first approach was correct for value 1, but the underflow makes betLimit very large so 1 != max. I need to choose a value that equals the underflow result (impossible). Better: use the revert-on-wager difference. But the problem asks that the reference passes and bug fails; the initial setup must allow the wager to succeed on reference but fail on bug, or vice versa.
// Let's do: owner calls AdjustBetAmounts(1). Reference: betLimit=1. Bug: betLimit=0. Then player wagers 1: reference succeeds, bug reverts. That is the already-tried pattern! The instruction says it was already tried. So I must pick a different scenario.
// Another difference: After AdjustBetAmounts(0), reference betLimit=0; bug betLimit = max. Then set difficulty to 2 and player wagers 0 (value 0). Reference: wager(0) allowed (betLimit=0, msg.value=0, passes). Bug: wager(0) reverts because 0 != max. Then player calls play(): reference has wager, bug doesn't. Assert that c.hasPlayerWagered(player) is true on reference, false on bug.
// That is a concrete divergence.

// Let's rewrite the test properly:
contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        c.OpenToThePublic();
        c.AdjustDifficulty(2);

        // Owner calls AdjustBetAmounts(0)
        vm.prank(address(this));
        c.AdjustBetAmounts(0);

        address player = address(0x1234);
        vm.deal(player, 0);
        vm.prank(player);
        c.wager{value: 0}();

        // Reference: wager succeeds, wagers[player] > 0
        // Bug: wager reverts, so wagers[player] stays 0
        assertTrue(c.hasPlayerWagered(player));
    }
}

