    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Owner opens to public and sets difficulty to 10, betLimit to 8
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustDifficulty(10);
        vm.prank(address(this));
        c.AdjustBetAmounts(8);

        // Fund an account 10 eth, then wager 8 eth
        address player = address(0x1234);
        vm.deal(player, 10 ether);
        vm.prank(player);
        c.wager{value: 8 ether}();

        // Move block to allow play (player's timestamp block is current, so need to go forward)
        vm.roll(block.number + 1);

        // Attempt play; for reference contract, winningNumber = hash(...)%10+1, 
        // correct win if == 5 (difficulty/2). With this concrete data, we need a specific hash
        // so that winningNumber == 5 (for reference) but bug breaks because bug checks == 6.
        // We cannot control the hash directly, but we can choose the expected behavior:
        // The test will pass on reference and fail on bug if reference sends 4 eth to player
        // and bug sends 0 (sends whale) or vice versa. To guarantee a difference, we rely on
        // the fact that for this concrete run, the hash will yield some winningNumber.
        // However, the test must work deterministically. We'll use a scenario where we know
        // the reference passes and bug fails by checking the resulting balance of the contract
        // or the player. Since the hash is unpredictable, we instead check the revert behavior:
        // The bug always uses +1, so we set difficulty=2, betLimit=8, then winningNumber is
        // 0 or 1 plus 1 => 1 or 2. Reference win if == 1 (difficulty/2=1), bug win if == 2.
        // Now we can hardcode a scenario: player wagers, then we call play and assert
        // that the contract balance after is as expected for the reference.

        // Re-deploy with difficulty=2
        c = new C(address(this), 0);
        vm.prank(address(this));
