        c.donate{value: 1 ether}();  // donate 1 ether

        // Assert: totalDonated should have increased by 1 ether (reference) vs unchanged (bug)
        uint256 afterDonation = c.totalDonated();
        assertTrue(afterDonation == beforeDonation + 1 ether);
    }
}

