pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set up state: open to public, set betLimit to 0, and make a wager
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.wager{value: 0}();

        // Now call play() — this will succeed because difficulty is 0, so winningNumber calculation mod 0 will revert in some impl, but actually it will cause a revert due to division by zero? 
        // Actually difficulty is 0, but winningNumber = ... % 0 causes revert. So use a non-zero difficulty.
        // Set difficulty to 1.
        vm.prank(address(this));
        c.AdjustDifficulty(1);

        // Now play() will succeed because blockhash(blockNumber) is nonzero.
        vm.prank(address(this));
        c.play();

        // After play, the contract may have sent half balance to winner and half to whale.
        // The ethBalance() returns address(this).balance in P, and address(this).balance + 1 in M.
        uint256 ethBal = c.ethBalance();
        uint256 actualBal = address(c).balance;
        // In reference P, ethBal == actualBal; in M, ethBal == actualBal + 1.
        // We assert that ethBal == actualBal (which holds only for P, fails for M).
        assertTrue(ethBal == actualBal);
    }
}

